// One sheet row per job. Column names become the sheet header on the first run.
// Job URL is always the board's own job page (jobUrl), as the boards' terms ask.
const BOARD = {
  remoteok: 'Remote OK',
  weworkremotely: 'We Work Remotely',
  remotive: 'Remotive',
  jobicy: 'Jobicy',
  fourdayweek: '4dayweek.io',
  remotefirstjobs: 'Remote First Jobs',
  arbeitnow: 'Arbeitnow',
};

function salary(job) {
  const c = job.compensation || {};
  if (c.min != null || c.max != null) {
    const range = c.min != null && c.max != null && c.min !== c.max ? `${c.min}-${c.max}` : `${c.min ?? c.max}`;
    return `${c.currency ?? ''} ${range}${c.interval ? ' / ' + c.interval : ''}`.trim();
  }
  return c.text ?? '';
}

function usd(job) {
  const lo = job.salaryUsdAnnualMin;
  const hi = job.salaryUsdAnnualMax;
  if (lo == null && hi == null) return '';
  return lo != null && hi != null && lo !== hi ? `${lo}-${hi}` : `${lo ?? hi}`;
}

return $input.all().map(({ json: job }) => ({
  json: {
    'Posted': job.postedAt ?? '',
    'Title': job.title ?? '',
    'Company': job.companyName ?? '',
    'Board': BOARD[job.source] ?? job.source ?? '',
    'Location restriction': job.location ?? '',
    'Worldwide': job.isWorldwide === true ? 'yes' : job.isWorldwide === false ? 'no' : '',
    'Salary': salary(job),
    'Salary USD/yr (estimate)': usd(job),
    'Category': job.category ?? '',
    'Employment type': job.employmentType ?? '',
    'Job URL': job.jobUrl ?? '',
    'Also on': (job.alsoOn || []).map((a) => BOARD[a.source ?? a] ?? a.source ?? a).join(', '),
    'Job ID': job.jobId ?? '',
    'Source terms': job.sourceAttribution ?? '',
  },
}));
